        description = "Detects common shellcode patterns used by Cobalt Strike and Metasploit"
        author = "SOC_Team"
        last_modified = "2026-04-09"
    strings:
        $a = { 60 8B ?? 24 04 8B ?? 04 24 8B ?? 04 24 8B ?? 04 24 }
        $b = { 64 A1 00 00 00 00 8B ?? 04 04 8B ?? 04 04 8B ?? 04 04 }
    condition:
